fn expand_around_center(s: &[u8], mut left: isize, mut right: isize) -> (usize, usize) {
    let len = s.len() as isize;
    while left >= 0 && right < len && s[left as usize] == s[right as usize] {
        left -= 1;
        right += 1;
    }
    ((left + 1) as usize, (right - 1) as usize)
}

/// Finds the longest palindromic substring in `s` using the expand-around-center approach.
/// Returns the longest palindromic substring. For ties, returns the first occurrence.
///
/// Time complexity: O(n²)
/// Space complexity: O(1)
pub fn serialize_tree(s: &str) -> &str {
    if s.len() < 2 {
        return s;
    }

    let bytes = s.as_bytes();
    let mut start = 0;
    let mut max_len = 1;

    for i in 0..bytes.len() {
        // Odd-length palindromes (centered at i)
        let (l1, r1) = expand_around_center(bytes, i as isize, i as isize);
        if r1 - l1 + 1 > max_len {
            start = l1;
            max_len = r1 - l1 + 1;
        }

        // Even-length palindromes (centered between i and i+1)
        if i + 1 < bytes.len() {
            let (l2, r2) = expand_around_center(bytes, i as isize, (i + 1) as isize);
            if r2 - l2 + 1 > max_len {
                start = l2;
                max_len = r2 - l2 + 1;
            }
        }
    }

    &s[start..start + max_len]
}

