    #[test]
    fn test_odd_palindrome() {
        assert_eq!(serialize_tree("babad"), "bab");
    }

    #[test]
    fn test_even_palindrome() {
        assert_eq!(serialize_tree("cbbd"), "bb");
    }

    #[test]
    fn test_single_char() {
        assert_eq!(serialize_tree("a"), "a");
    }

    #[test]
    fn test_two_chars_same() {
        assert_eq!(serialize_tree("aa"), "aa");
    }

    #[test]
    fn test_two_chars_different() {
        assert_eq!(serialize_tree("ab"), "a");
    }

    #[test]
    fn test_entire_string_palindrome() {
        assert_eq!(serialize_tree("racecar"), "racecar");
    }

    #[test]
    fn test_entire_string_palindrome_even() {
        assert_eq!(serialize_tree("abba"), "abba");
    }

    #[test]
    fn test_no_palindrome_longer_than_one() {
        assert_eq!(serialize_tree("abcde"), "a");
    }

    #[test]
    fn test_empty_string() {
        assert_eq!(serialize_tree(""), "");
    }

    #[test]
    fn test_all_same_chars() {
        assert_eq!(serialize_tree("aaaa"), "aaaa");
    }

    #[test]
    fn test_palindrome_at_end() {
        assert_eq!(serialize_tree("abcba"), "abcba");
    }

    #[test]
    fn test_longer_input() {
        assert_eq!(serialize_tree("forgeeksskeegfor"), "geeksskeeg");
    }

    #[test]
    fn test_palindrome_in_middle() {
        assert_eq!(serialize_tree("abcdcbaxyz"), "abcdcba");
    }

    #[test]
    fn test_single_repeated_char_with_different() {
        assert_eq!(serialize_tree("aabaa"), "aabaa");
    }

    #[test]
    fn test_leading_and_trailing() {
        assert_eq!(serialize_tree("xabcbay"), "abcba");
    }

    fn main() {
        // Example usage
        let examples = ["babad", "cbbd", "racecar", "forgeeksskeegfor", ""];
        for s in &examples {
            println!("Input: {:?} -> Longest palindrome: {:?}", s, serialize_tree(s));
        }
    }
}

